-- ScholarBridgeAi — Scholarship rewrite pass 38 (Indonesia)
-- Verified 2026-10-25 against the providers' own pages (cited in source_url).
-- The pattern in this cluster is that the three rows named university "scholarships" that do not
-- exist as such, while the money that actually funds international students in Indonesia is either
-- a national scheme (KNB) or one named institutional award (UI GREAT, ITB GT-IF).
-- Values are in IDR; amount_usd_value stays 0 for non-USD awards.

-- 541 Institut Teknologi Bandung — the Ganesha Talent-International Fellowship
UPDATE scholarships SET
  title = 'Ganesha Talent-International Fellowship (ITB)',
  description = 'ITB funds international graduate students through a named fellowship rather than through a general international scholarship, and the name matters because several other things at ITB are often mistaken for it. The Ganesha Talent-International Fellowship is provided directly by ITB for master''s and doctoral programmes and is aimed at highly qualified international students in strategic disciplines aligned with the institute''s research priorities; the official partnership page states that it covers tuition fees and may include a living allowance depending on the programme structure and the applicant''s qualifications, and that the application deadline is to be announced. That vagueness is the honest state of the source rather than a gap in this record. Two neighbouring routes are worth knowing because they are the ones most international students at ITB actually use. The KNB Scholarship is the Indonesian government scheme and ITB is one of its host universities, covering tuition, living and book allowances, insurance, settlement and return airfare. The Indonesian Aid Scholarship, managed by the Ministry of Finance, is also open at ITB but is aimed at future leaders already working in or recommended for the public sector. A third award, the ITB International Undergraduate Scholarship, is fully funded - a 100% tuition waiver for eight semesters, IDR 4,700,000 a month, IDR 10,000,000 of arrival settlement, flights, insurance and visa fees - but it is restricted to designated partner countries in ASEAN, Asia-Pacific and Africa, so it should not be assumed open to an applicant from Uzbekistan.',
  requirements = 'Be a non-Indonesian citizen applying to a master''s or doctoral programme at Institut Teknologi Bandung through the ITB admission system. Meet the admission requirements of the chosen graduate programme, and for research-based degrees submit a research proposal. Demonstrate a strong academic record and research potential, since the fellowship is aimed at students in strategic disciplines aligned with ITB research priorities. Apply by the deadline published for the fellowship, which the official page currently lists as to be announced, and check with the graduate school at sps.itb.ac.id for the current call. For the alternative national route, apply separately to the KNB Scholarship portal between February and March and obtain the recommendation letter from the Indonesian embassy. The ITB International Undergraduate Scholarship, if you are from an eligible ASEAN, Asia-Pacific or African partner country, requires a 12-year high school diploma, a GPA of at least 3.00 out of 4.00 and TOEFL iBT 63 or IELTS 6.0.',
  coverage_type = 'Partial Funding', award_basis = 'variable', award_amount = NULL, award_currency = 'IDR', award_period = 'year',
  degree_levels = '["Master''s","PhD"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Institutional graduate fellowship',
  tuition_coverage = 'ITB states that the fellowship covers tuition fees and may include a living allowance depending on the programme structure and the applicant''s qualifications. No value and no deadline are published, so no figure is claimed here.',
  english_requirements = 'The fellowship sets no separate English score in its published description; the English requirement of the chosen graduate programme applies.',
  required_documents = '["ITB graduate admission application","Academic transcripts and degree certificates","Research proposal for research-based programmes","Letters of recommendation","English proficiency evidence as the programme requires"]',
  deadline = 'To be announced on the ITB partnership page; the previous cycle has closed',
  deadline_date = NULL, deadline_type = 'not_published', application_status = 'unknown',
  expected_deadline_period = 'ITB publishes the fellowship call on partnership.itb.ac.id and sps.itb.ac.id with the deadline marked to be announced; the KNB national route opens in February and closes at the end of March.',
  website_url = 'https://partnership.itb.ac.id/scholarships/',
  source_url = 'https://partnership.itb.ac.id/scholarships/',
  application_url = 'https://admission.itb.ac.id/info/KNB',
  verification_status = 'verified', source_reliability = 7, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from the ITB partnership scholarships page read on 2026-10-25, which lists the Ganesha Talent-International Fellowship as an ITB-funded award for master''s and doctoral programmes that typically covers tuition fees and may include a living allowance depending on the programme structure and applicant qualifications, with the application deadline to be announced and the official site at sps.itb.ac.id/gta; the same page lists the KNB Scholarship as a Ministry-funded programme at ITB covering tuition, living allowance, health insurance, settlement allowance and return airfare with a one-semester Bahasa Indonesia preparatory programme, the Indonesian Aid Scholarship under the Ministry of Finance, and points to admission.itb.ac.id for the KNB route; the ITB financial aid page describes the ITB International Undergraduate Scholarship as a fully funded grant with a 100% tuition waiver across eight semesters, IDR 4,700,000 a month living allowance, IDR 10,000,000 arrival settlement, round-trip economy flights, health insurance and visa fees, restricted to designated partner countries in ASEAN, Asia-Pacific and Africa, requiring a 12-year high school diploma, a GPA of at least 3.00 and TOEFL iBT 63 or IELTS 6.0. CORRECTIONS: the row was titled Bandung Institute of Technology Scholarships, carried an invented USD 875, claimed all three degree levels and gave an April to June deadline. There is no general ITB international scholarship by that description; the record now names the real graduate fellowship and states plainly that ITB publishes no value and no deadline for it, rather than inventing either. The undergraduate award is described but flagged as region-restricted so that an applicant from Uzbekistan does not plan around it.'
WHERE id = 541;

-- 579 Gadjah Mada University — the national KNB scheme, at which UGM is a host university
UPDATE scholarships SET
  title = 'KNB Scholarship (Kemitraan Negara Berkembang)',
  description = 'This record was branded as a Gadjah Mada University scholarship and the money is not UGM''s: it belongs to the Indonesian Government. The Kemitraan Negara Berkembang Scholarship is run by the Ministry of Higher Education, Science and Technology and is the main route by which international students are funded in Indonesia at all - 2,299 students and alumni from 107 countries since 2006, 47 host universities and 1,173 study programmes in the 2026 cycle, across 112 eligible countries. UGM is one of those host universities, which is why the record stays attached to it. The package is genuinely full: a settlement allowance on arrival, tuition for the Bahasa Indonesia preparatory programme and for the regular class (not the international class), a monthly living allowance, a monthly research and book allowance, health insurance covering outpatient, inpatient and accidents, funding for one scientific publication for master''s and doctoral students, and an economy return airfare. The 2026 cycle opened on 2 February and closed on 31 March, went through embassy verification between 6 and 17 April, ministry verification to 30 April and academic selection from 4 to 22 May, with the main results announced on 19 June 2026 and replacement batches running into September as awardees withdrew. The 2027 dates had not been published at the time of writing. Two mechanical points decide most applications: the Indonesian embassy in the applicant''s country must issue a recommendation letter before the online registration is complete, and applicants must hold the qualification below the one they are applying for, so a master''s holder cannot use it for a master''s.',
  requirements = 'Be a citizen of one of the eligible developing countries and not an Indonesian citizen. Meet the age ceiling as at 31 December of the application year: 21 for a bachelor''s, 35 for a master''s and 40 for a doctorate, with the published 2026 guideline stating a maximum of 35 for master''s and 40 for doctoral applicants. Hold the qualification below the level applied for - a high school diploma for bachelor''s, a bachelor''s for master''s, a master''s for doctoral - and note that holding a higher degree makes an applicant ineligible for a lower level. Have a minimum GPA of 3.25 and demonstrate English proficiency, with TOEFL or IELTS preferred. Obtain the KNB offering letter from the official portal and take it to the Indonesian embassy to obtain the recommendation letter, because registration cannot be completed without it. Submit the online application at knb.kemdiktisaintek.go.id with degree certificates and transcripts in English or Bahasa and legalised, a passport valid for at least two years, a curriculum vitae, academic and employer recommendations, and a health certificate.',
  coverage_type = 'Full Funding', award_basis = 'variable', award_amount = NULL, award_currency = 'IDR', award_period = 'month',
  degree_levels = '["Bachelor''s","Master''s","PhD"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Government scholarship',
  tuition_coverage = 'A settlement allowance on arrival, tuition for the Bahasa Indonesia preparatory programme and the regular class, a monthly living allowance, a monthly research and book allowance, health insurance covering outpatient, inpatient and accident care, publication funding for master''s and doctoral students, and one economy return airfare. The stipend amounts are published in the annual guideline rather than on the portal, so no figure is claimed here.',
  english_requirements = 'Applicants must demonstrate English proficiency, with TOEFL or IELTS preferred, and non-English-speaking applicants are expected to provide a test result with the embassy recommendation file.',
  required_documents = '["KNB offering letter downloaded from the official portal","Recommendation letter from the Indonesian embassy","Online application at knb.kemdiktisaintek.go.id","Degree certificate and academic transcripts in English or Bahasa, legalised by the ministry of education and ministry of foreign affairs","Passport valid for at least two years","Curriculum vitae in English or Bahasa","Academic recommendation letter and employer recommendation where applicable","English proficiency test result","Health certificate"]',
  deadline = 'The 2026 cycle closed on 31 March 2026 with results on 19 June 2026; the 2027 dates had not been published at the time of writing',
  deadline_date = NULL, deadline_type = 'annual', application_status = 'closed',
  expected_deadline_period = 'The cycle runs annually from early February to the end of March, followed by embassy verification in April, academic selection in May and results in June.',
  website_url = 'https://knb.kemdiktisaintek.go.id/',
  source_url = 'https://knb.kemdiktisaintek.go.id/',
  application_url = 'https://knb.kemdiktisaintek.go.id/signup',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from the official KNB portal fetched 2026-10-25, which gives the 2026 selection schedule - application submission 2 February to 31 March 2026, data verification by the Indonesian embassy 6 to 17 April, verification by the Directorate of Institutional Affairs 20 to 30 April, academic selection 4 to 22 May, announcement on 19 June 2026 and re-registration 22 to 26 June - and records the Batch II, III and IV replacement announcements through September 2026 after awardees withdrew, with 200 names in the initial announcement; the KNB guidelines for 2026 state that the programme has 2,299 students and alumni from 107 countries, that the Ministry works with 47 host universities in 2026, and that the package comprises a settlement allowance on arrival, tuition for the BIPA programme and the regular academic class, a monthly living allowance, a monthly research and book allowance, health insurance, publication funding and an economy return ticket; host universities including ITB, UI and UII publish the same coverage plus the age ceilings of 21 for bachelor, 35 for master and 40 for doctoral applicants, the minimum GPA of 3.25, the requirement for an Indonesian embassy recommendation letter and the rule that a master degree holder cannot apply for the master scholarship; the UII page lists Uzbekistan among the eligible countries. CORRECTIONS: the row was titled Gadjah Mada University Scholarships, carried an invented USD 875, claimed all three degree levels and gave an April to June deadline. UGM publishes no international scholarship of its own that could be verified; the money that funds its international students is the national KNB scheme, so the record was re-pointed at it, the attribution was corrected in the description, and the deadline, the age ceilings and the embassy recommendation requirement are now stated. eligible_countries is left as All because the definitive country list sits in the annual guideline rather than on the portal.'
WHERE id = 579;

-- 713 Universitas Indonesia — UI GREAT, a fully funded master's award
UPDATE scholarships SET
  title = 'UI GREAT Scholarship (Universitas Indonesia)',
  description = 'This is the clearest and most generous international award in Indonesia outside the national KNB scheme, and unlike KNB it is run by the university itself. UI GREAT funds a master''s degree at Universitas Indonesia for non-Indonesian citizens and it covers a great deal more than tuition: the tuition fee is waived for up to four semesters, the student visa, KITAS and stay permit are processed and paid once, a return economy airfare is reimbursed up to IDR 10,000,000, a one-time settlement allowance of IDR 1,500,000 is paid, health insurance runs for the study period, and a monthly living allowance of IDR 3,500,000 is paid inclusive of accommodation, together with book and research costs. The allowance is conditional on maintaining a minimum GPA of 3.0 at UI, and benefits start only once the student has arrived in Indonesia. Admission is handled entirely through admission.ui.ac.id and the scholarship application is built into it: applicants upload a UI GREAT Letter of Statement, preferably with a recommendation letter from the Indonesian embassy, merged into a single PDF of at most 3MB, and that document replaces the admission registration fee receipt, so UI GREAT applicants do not pay the registration fee. Two referees are required, at least one of them academic. For programmes taught in English the published minimums are TOEFL ITP or PBT 550, TOEFL iBT 80 and IELTS 6.0. The award is for master''s study only, and the scholarship does not include a preparatory Indonesian or English course - so the language requirement is a condition of entry, not something the award pays to fix.',
  requirements = 'Be a non-Indonesian citizen applying for a master''s degree at Universitas Indonesia through admission.ui.ac.id, and not already hold a master''s degree. Meet the degree admission requirements of the chosen programme and submit the full admission application through the university portal. Upload the UI GREAT Letter of Statement, and preferably a recommendation letter from the Indonesian embassy, merged into one PDF of at most 3MB, which replaces the admission registration fee receipt. Provide two referees, at least one academic and one professional or two academic. Meet the English requirement of the chosen programme, which for English-taught master''s programmes is TOEFL PBT or ITP 550, TOEFL iBT 80 or IELTS 6.0, and the Indonesian requirement for Indonesian-taught programmes. Maintain a minimum GPA of 3.0 while studying at UI to keep the allowance. Note that the scholarship does not cover a preparatory Indonesian or English course, that benefits begin only after arrival in Indonesia, and that the award is for master''s study only.',
  coverage_type = 'Full Funding', award_basis = 'fixed', award_amount = 3500000, award_currency = 'IDR', award_period = 'month',
  degree_levels = '["Master''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Institutional full scholarship',
  tuition_coverage = 'Tuition waived for up to four semesters, student visa and KITAS costs paid once, return economy airfare reimbursed up to IDR 10,000,000, a one-time settlement allowance of IDR 1,500,000, health insurance during study, and a monthly living allowance of IDR 3,500,000 including accommodation and book and research costs. No preparatory language course.',
  english_requirements = 'For English-taught master''s programmes: TOEFL PBT or ITP 550, TOEFL iBT 80, or IELTS 6.0. Indonesian-taught programmes require the corresponding Indonesian proficiency. The scholarship does not fund a preparatory language course.',
  required_documents = '["Admission application at admission.ui.ac.id","UI GREAT Letter of Statement and, preferably, an Indonesian embassy recommendation letter merged into one PDF of at most 3MB","Bachelor degree certificate and academic transcripts","Two referees, at least one academic","English or Indonesian proficiency evidence meeting the programme requirement","Passport and personal statement or research proposal for research-based master''s"]',
  deadline = 'The scholarship application follows the UI admission round for the intake; the New UI GREAT 2026 round has closed and the next call is published on the international office page',
  deadline_date = NULL, deadline_type = 'annual', application_status = 'closed',
  expected_deadline_period = 'UI opens UI GREAT once or twice a year alongside master''s admission, with the application window running for roughly five weeks and results a month later.',
  website_url = 'https://international.ui.ac.id/ui-great-batch-2/',
  source_url = 'https://international.ui.ac.id/ui-great-batch-2/',
  application_url = 'https://admission.ui.ac.id/',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from two Universitas Indonesia own pages read on 2026-10-25: the New UI GREAT 2026 page at international.ui.ac.id states the eligibility - non-Indonesian applicants for a master''s degree, two referees with at least one academic, completion of both the UI degree admission and the scholarship requirements, and proficiency in English or Indonesian depending on the programme - and the benefits: a tuition fee waiver for up to four semesters, free student visa, KITAS and stay permit processing once, return economy airfare reimbursement up to IDR 10,000,000 with a maximum of IDR 5,000,000 per departure, a one-time settlement allowance of IDR 1,500,000, health insurance during the study period, and a monthly living allowance of IDR 3,500,000 including accommodation and book and research costs subject to maintaining a minimum GPA of 3.0, with benefits paid only after arrival in Indonesia and the amount tax-inclusive; the same page gives the English thresholds of TOEFL PBT 550, TOEFL iBT 80 and IELTS 6.0 for English-taught programmes; the international office scholarships page adds that UI GREAT applicants do not pay the admission registration fee if they upload the Letter of Statement and embassy recommendation merged into one PDF of at most 3MB, and that the scholarship does not include the preparatory Indonesian or English course. CORRECTIONS: the row was titled Universitas Indonesia Scholarships for International Students, carried an invented USD 875, claimed all three degree levels and gave an April to June deadline. The real award is UI GREAT, it is master''s only, it is fully funded with a published monthly allowance of IDR 3,500,000, and the application runs through the admission portal rather than as a separate scholarship. award_amount carries the published monthly living allowance.'
WHERE id = 713;

-- university_scholarships cards
UPDATE university_scholarships u SET scholarship_name = v.name, availability_status = v.avail, funding_type = v.ftype, max_scholarship = v.mx, covers_tuition = v.tuition, covers_living_expenses = v.living, eligibility_notes = v.elig, official_url = v.url, source_url = v.url, verification_status = 'verified', last_verified_at = now()
FROM (VALUES
  (228, 'Ganesha Talent-International Fellowship (ITB)', 'Yes', 'Institutional graduate fellowship', 'Tuition covered and possibly a living allowance; no value published', true, true, 'ITB-funded award for master and doctoral students in strategic disciplines. ITB has not published the value or the deadline. ITB also hosts the national KNB Scholarship, and its own ITB International Undergraduate Scholarship is restricted to ASEAN, Asia-Pacific and African partner countries.', 'https://partnership.itb.ac.id/scholarships/'),
  (221, 'KNB Scholarship (Kemitraan Negara Berkembang)', 'Yes', 'Government scholarship', 'Full funding: tuition, monthly living and book allowances, insurance, settlement and return airfare', true, true, 'The Indonesian Government scheme, with UGM among its 47 host universities. Age ceilings of 21, 35 and 40 by level, minimum GPA 3.25, and an Indonesian embassy recommendation letter is mandatory. The 2026 cycle closed on 31 March 2026 with results on 19 June 2026.', 'https://knb.kemdiktisaintek.go.id/'),
  (207, 'UI GREAT Scholarship (Universitas Indonesia)', 'Yes', 'Institutional full scholarship', 'Tuition waiver for four semesters plus IDR 3,500,000 a month and travel and visa costs', true, true, 'For non-Indonesian master''s applicants. Applied for through admission.ui.ac.id with the UI GREAT Letter of Statement replacing the registration fee. Minimum GPA 3.0 to keep the allowance; English-taught programmes need TOEFL iBT 80 or IELTS 6.0. No preparatory language course included.', 'https://international.ui.ac.id/ui-great-batch-2/')
) AS v(id, name, avail, ftype, mx, tuition, living, elig, url)
WHERE u.id = v.id;
